<script setup lang="ts">
import { ref,computed,onMounted } from 'vue'
import { useQuasar } from 'quasar'
import { Plus,ShieldCheck,Users,Search } from 'lucide-vue-next'
import { api,allPages } from '../services/api'
import { useMonitor } from '../stores/monitor'
type Account={id:number;username:string;first_name:string;last_name:string;email:string;is_active:boolean;is_admin:boolean}
type Access={server:number;role:string}
const store=useMonitor(),$q=useQuasar()
const users=ref<Account[]>([]),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),dialog=ref(false),accessDialog=ref(false),selected=ref<Account|null>(null),assignments=ref<Access[]>([])
const blank=()=>({username:'',first_name:'',last_name:'',email:'',password:'',is_active:true,is_admin:false})
const form=ref(blank())
const filtered=computed(()=>users.value.filter(u=>`${u.username} ${u.first_name} ${u.last_name} ${u.email}`.toLowerCase().includes(search.value.toLowerCase())))
async function load(){if(!store.user?.is_admin)return;loading.value=true;try{users.value=await allPages<Account>('/users')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function edit(user:Account|null){selected.value=user;form.value=user?{...blank(),...user}:blank();error.value='';dialog.value=true}
async function save(){busy.value=true;error.value='';try{const {password,...fields}=form.value;await api(selected.value?`/users/${selected.value.id}`:'/users',{method:selected.value?'PATCH':'POST',body:JSON.stringify({...fields,...(password?{password}:{})})});dialog.value=false;await load();$q.notify({message:'User saved',color:'positive'})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function access(user:Account){error.value='';selected.value=user;busy.value=true;try{assignments.value=await api(`/users/${user.id}/access`);accessDialog.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function role(server:number){return assignments.value.find(a=>a.server===server)?.role||'none'}
function setRole(server:number,value:string){assignments.value=assignments.value.filter(a=>a.server!==server);if(value!=='none')assignments.value.push({server,role:value})}
async function saveAccess(){busy.value=true;error.value='';try{await api(`/users/${selected.value!.id}/access`,{method:'PUT',body:JSON.stringify(assignments.value)});accessDialog.value=false;await store.refresh();$q.notify({message:'Access roles saved',color:'positive'})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<div class="page-header"><div><h1>Users & roles</h1><p class="subtitle">Manage accounts and access to your infrastructure.</p></div><q-btn v-if="store.user?.is_admin" color="primary" unelevated no-caps @click="edit(null)"><Plus :size="18"/>Add user</q-btn></div>
<div v-if="!store.user?.is_admin" class="notice" role="alert">Only platform administrators can manage users and access roles.</div>
<template v-else>
<div v-if="error&&!dialog&&!accessDialog" class="error-box" role="alert">{{error}}<q-btn flat label="Retry" @click="load"/></div>
<section class="panel"><header class="panel-header"><h2><Users :size="19"/>User accounts</h2></header><div class="settings-body"><q-input v-model="search" outlined dense label="Search users" clearable @clear="search=''" ><template #prepend><Search :size="18"/></template></q-input><q-linear-progress v-if="loading" indeterminate class="q-mt-md"/>
<div v-for="u in filtered" :key="u.id" class="user-row"><div class="user-identity"><b>{{u.username}}</b><small class="muted block">{{[u.first_name,u.last_name].filter(Boolean).join(' ')||u.email||'No profile details'}}</small></div><span class="muted">{{u.is_admin?'Platform administrator':'Team member'}} · {{u.is_active?'Active':'Inactive'}}</span><div class="button-row"><q-btn outline no-caps label="Edit user" :aria-label="`Edit user ${u.username}`" @click="edit(u)"/><q-btn flat no-caps label="Access roles" :aria-label="`Access roles for ${u.username}`" :disable="busy" @click="access(u)"/></div></div><p v-if="!loading&&!filtered.length" class="muted q-mt-md">No users found.</p></div></section>
<section class="panel q-mt-lg"><header class="panel-header"><h2><ShieldCheck :size="19"/>Role permissions</h2></header><div class="settings-body"><p><b>Platform administrator</b> — manages all users and servers, including account and role assignments.</p><p><b>Server Admin</b> — configures an assigned server, applications, alert rules, maintenance, and server membership; handles incidents.</p><p><b>Operator</b> — views assigned servers and acknowledges or comments on incidents.</p><p><b>Viewer</b> — reads assigned servers, applications, metrics, and incidents.</p><p class="muted">Team members have no server access until assigned. Server roles apply to each server and its applications. Platform administrators always have access to every server.</p></div></section>
</template>
<q-dialog v-model="dialog" persistent><q-card class="form-dialog"><form @submit.prevent="save"><q-card-section><h2>{{selected?'Edit user':'Add user'}}</h2></q-card-section><q-card-section class="form-fields"><q-input v-model="form.username" outlined label="Username" maxlength="150" required autocomplete="off"/><div class="form-two"><q-input v-model="form.first_name" outlined label="First name" maxlength="150"/><q-input v-model="form.last_name" outlined label="Last name" maxlength="150"/></div><q-input v-model="form.email" outlined label="Email" type="email" maxlength="254"/><q-input v-model="form.password" outlined :label="selected?'New password (leave blank to keep)':'Password'" type="password" :required="!selected" autocomplete="new-password"/><q-toggle v-model="form.is_active" label="Active account" :disable="selected?.id===store.user?.id"/><q-toggle v-model="form.is_admin" label="Platform administrator" :disable="selected?.id===store.user?.id"/><p class="muted">Platform administrators can manage every account and server. Deactivating an account prevents API access and sign-in.</p><div v-if="error" class="error-box" role="alert">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" :disable="busy" v-close-popup/><q-btn type="submit" color="primary" unelevated no-caps label="Save user" :loading="busy"/></q-card-actions></form></q-card></q-dialog>
<q-dialog v-model="accessDialog" persistent><q-card class="form-dialog"><q-card-section><h2>Access roles · {{selected?.username}}</h2><p v-if="selected?.is_admin" class="notice">This platform administrator already has full access. These assignments apply if administrator access is removed.</p></q-card-section><q-card-section class="form-fields"><q-select v-for="s in store.data?.servers||[]" :key="s.id" :model-value="role(s.id)" @update:model-value="setRole(s.id,$event)" :label="s.name" outlined emit-value map-options :options="[{label:'No access',value:'none'},{label:'Viewer',value:'viewer'},{label:'Operator',value:'operator'},{label:'Admin',value:'admin'}]"/><p v-if="!store.data?.servers.length" class="muted">Register a server to assign access.</p><div v-if="error" class="error-box" role="alert">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" :disable="busy" v-close-popup/><q-btn color="primary" unelevated no-caps label="Save access roles" :loading="busy" @click="saveAccess"/></q-card-actions></q-card></q-dialog>
</template>
<style scoped>.user-row{display:flex;align-items:center;gap:20px;flex-wrap:wrap;padding:18px 0;border-bottom:1px solid #edf0f4}.user-identity{flex:1;min-width:150px;overflow-wrap:anywhere}.user-row .button-row{margin:0}@media(max-width:600px){.user-row{gap:12px}.user-row>span{width:100%}}</style>
